+}
+
+func (b *chBoundedReader) str() (string, error) {
+	n, err := b.r.StrLen()
+	if err != nil {
+		return "", err
+	}
+	if n > b.max {
+		return "", io.ErrUnexpectedEOF
+	}
+	if n == 0 {
+		return "", nil
+	}
+	buf := make([]byte, n)
+	if _, err := io.ReadFull(b.r, buf); err != nil {
+		return "", err
+	}
